import React from 'react';
import { FaHome, FaSearch, FaBell, FaUser, FaComments, FaPlusCircle } from 'react-icons/fa'; // FaComments instead of FaThreads

const Sidebar = () => {
  return (
    <div className="sidebar">
      <ul>
        <li>
          <FaHome /> Home
        </li>
        <li>
          <FaSearch /> Search
        </li>
        <li>
          <FaComments /> Threads {/* Replaced FaThreads with FaComments */}
        </li>
        <li>
          <FaBell /> Notifications
        </li>
        <li>
          <FaUser /> Profile
        </li>
        <li>
          <FaPlusCircle /> Create
        </li>
      </ul>
    </div>
  );
};

export default Sidebar;
